import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数低通滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/complex_low_pass/index.md","filePath":"v0.3.0-alpha/modules/complex_low_pass/index.md"}'),c={name:"v0.3.0-alpha/modules/complex_low_pass/index.md"};function r(n,t,l,i,h,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="复数低通滤波器" tabindex="-1">复数低通滤波器 <a class="header-anchor" href="#复数低通滤波器" aria-label="Permalink to &quot;复数低通滤波器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_low_pass</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>对复数输入执行低通滤波，保留零频率附近的基带成分。实系数抽头以相同方式作用于 I 和 Q，适合观察复数基带的带宽限制。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数混合信号.out → 复数低通滤波器.in</code>。观察输出的 I/Q 与双边频谱，也可同时保留输入作为对照。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>输入采样率应等于上游实际速率。低通通带围绕零频率，复数频谱中的正、负频率都要按其与零的距离理解；不能把负频率直接当成需要删除的数据。</p><p>截止频率、过渡带与窗共同决定抽头。插值设计按提高后的采样率进行；抽取与插值至多一个大于 1。降采样前要限制实际占用带宽，避免混叠。</p><p><code>window_param</code> 随设计窗解释：Kaiser 使用 β（≥ 0）；Exponential 使用半窗长度上的衰减 d（dB，≥ 0）；Gaussian 使用 σ（&gt; 0）；Tukey 使用 α（0 ≤ α ≤ 1）。这个参数只对相应四种窗有意义，其他窗不靠它改变。切换窗后按新的含义检查数值，尤其不能给 Tukey 沿用超出 0 到 1 的旧值。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 5e-324 至 1000000；须等于上游实际采样率，可低于 1 Hz。插值滤波按输出采样率设计抽头。</td><td>重新准备</td></tr><tr><td>截止频率 (Hz)<br><code>cutoff_hz</code></td><td><code>256</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>过渡带宽 (Hz)<br><code>transition_hz</code></td><td><code>128</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>通带增益<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>设计窗函数<br><code>window</code></td><td><code>hamming</code></td><td>Hamming (<code>hamming</code>)；Hann (<code>hann</code>)；Blackman (<code>blackman</code>)；Rectangular (<code>rectangular</code>)；Kaiser (<code>kaiser</code>)；Blackman-Harris (<code>blackman_harris</code>)；Bartlett (<code>bartlett</code>)；Flat top (<code>flattop</code>)；Nuttall (<code>nuttall</code>)；Nuttall CFD (<code>nuttall_cfd</code>)；Welch (<code>welch</code>)；Parzen (<code>parzen</code>)；Exponential (<code>exponential</code>)；Riemann (<code>riemann</code>)；Gaussian (<code>gaussian</code>)；Tukey (<code>tukey</code>)</td><td>可在线应用</td></tr><tr><td>窗参数<br><code>window_param</code></td><td><code>6.76</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code>、<code>transition_hz</code>、<code>window</code>、<code>window_param</code>、<code>cutoff_hz</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>设计字段按组应用。若新抽头长度超过本次准备容量，停止并重新准备。速率关系变化后也需要重新准备；I/Q 的旧样本不会用新滤波器重算。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例的混合信号包含 64 Hz 和 768 Hz 相量及噪声。低通输出应保留低频相量并衰减较高频率。比较双边频谱时沿用实际复数幅值定义，不把正负频率幅度重复相加。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么 I 与 Q 都有滤波后的变化？</strong> 它们属于同一复数信号，实系数滤波分别作用于两个分量。</p><p><strong>只想截取偏离零的一个频段？</strong> 使用复数带通滤波器，按所需频带和系数模式选择。</p>',29)])])}const u=d(c,[["render",r]]);export{m as __pageData,u as default};
